// EXPIRY BRAIN - the only Code node. All the math lives here, in 5 labelled sections.
const cfg = $('Set Configuration Parameters').first().json;
const D = 86400000;
const now = new Date();
const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()) / D;
const dayNum = s => {
  const m = String(s ?? '').match(/(\d{4})-(\d{2})-(\d{2})/);
  return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) / D : NaN;
};
const rows = n => $(n).all().map(i => i.json);
const stock = rows('Read Branch Stock').filter(t => t.sku);
const sup = Object.fromEntries(rows('Read Supplier Policies').filter(s => s.supplier_id).map(s => [s.supplier_id, s]));
const branch = {};
for (const t of stock) branch[t.branch_id] ??= { name: t.branch_name || t.branch_id };
const run_date = new Date(today * D).toISOString().slice(0, 10);

// 1) SALES VELOCITY (60% last 30 days, 40% last 7 days)
const vel = {};
for (const s of rows('Read Sales Log').filter(s => s.date && s.sku)) {
  const age = today - dayNum(s.date);
  if (!(age >= 0 && age < 30)) continue;
  const k = s.branch_id + '|' + s.sku;
  vel[k] ??= { d30: 0, d7: 0 };
  vel[k].d30 += +s.qty || 0;
  if (age < 7) vel[k].d7 += +s.qty || 0;
}

// 2) FEFO EXPIRY PROJECTION (earliest-expiring batch sells first). Batches with a status are already handled: skipped.
const batches = rows('Read Inventory')
  .filter(b => b.batch_id && b.expiry_date && !String(b.status || '').trim())
  .map(b => {
    const v = vel[b.branch_id + '|' + b.sku] || { d30: 0, d7: 0 };
    return { ...b, qty: +b.qty || 0, unit_cost: +b.unit_cost || 0,
      velocity: +(0.6 * v.d30 / 30 + 0.4 * v.d7 / 7).toFixed(3),
      days_left: dayNum(b.expiry_date) - today };
  });
const groups = {};
for (const b of batches) (groups[b.branch_id + '|' + b.sku] ??= []).push(b);
for (const g of Object.values(groups)) {
  g.sort((a, b) => a.days_left - b.days_left);
  let consumed = 0;
  for (const b of g) {
    const demand = Math.max(0, b.velocity * Math.max(b.days_left, 0) - consumed);
    const sold = Math.min(b.qty, Math.floor(demand));
    consumed += sold;
    b.expiry_units = b.days_left <= 0 ? b.qty : b.qty - sold;
  }
}

const out = [];
for (const b of batches) {
  if (!(b.expiry_units > 0) || !(b.days_left <= cfg.horizon_days)) continue;

  // 3) PATIENT SAFETY FLAGS
  const f = [];
  const controlled = ['NDPS', 'H1'].includes(b.schedule);
  if (b.days_left <= 0) f.push('EXPIRED_QUARANTINE');
  if (['life-saving', 'chronic'].includes(b.criticality)) f.push('NEVER_STOCKOUT');
  if (b.storage === 'cold') f.push('COLD_CHAIN');
  if (controlled) f.push('CONTROLLED_MANUAL_COMPLIANCE');
  if (b.schedule === 'Rx') f.push('NO_PROMOTION');
  const needed = Math.max(+b.course_days || 0, cfg.min_dispense_days) + cfg.patient_buffer_days;
  const discountSafe = b.schedule === 'OTC' && b.days_left >= needed;   // OTC only, and the course must fit before expiry

  // 4) OPTIONS: best transfer + supplier return
  let best = null;
  if (b.days_left > 0) {
    for (const t of stock) {
      if (t.sku !== b.sku || t.branch_id === b.branch_id) continue;
      if (b.storage === 'cold' && t.cold_storage !== 'Y') continue;
      const usable = b.days_left - (+t.transit_days || 1) - 3;
      if (usable <= 0) continue;
      const need = Math.max(0, Math.floor(+t.avg_daily_sales * usable) - (+t.qty || 0));
      const units = Math.min(b.expiry_units, need);
      if (units > 0 && (!best || units > best.units)) best = { id: t.branch_id, name: t.branch_name || t.branch_id, email: t.branch_email || '', units };
    }
  }
  const s = sup[b.supplier_id] || null;
  const returnOk = !!s && b.days_left <= +s.pre_expiry_days && b.days_left >= -(+s.post_expiry_days || 0);

  // 5) DECISION LADDER: transfer > return > discount > dispose, plus reorder policy
  let rem = b.expiry_units;
  const plan = { transfer: 0, ret: 0, disc: 0, disp: 0 };
  if (b.days_left <= 0) { plan.disp = b.qty; rem = 0; }
  if (rem > 0 && best) { plan.transfer = Math.min(rem, best.units); rem -= plan.transfer; }
  if (rem > 0 && returnOk) { plan.ret = rem; rem = 0; }
  if (rem > 0 && discountSafe) { plan.disc = rem; rem = 0; }
  if (rem > 0) { plan.disp = rem; }
  const never = f.includes('NEVER_STOCKOUT');
  const minStock = Math.ceil(b.velocity * cfg.safety_days);
  const parts = [];
  if (plan.transfer) parts.push(`transfer ${plan.transfer} to ${best.name}`);
  if (plan.ret) parts.push(`return ${plan.ret} to ${s.supplier_name || s.supplier_id}`);
  if (plan.disc) parts.push(`discount ${plan.disc} (${cfg.discount_pct}% off)`);
  if (plan.disp) parts.push(b.days_left <= 0 ? `quarantine and dispose ${plan.disp}` : `dispose ${plan.disp}`);
  parts.push(never ? `keep at least ${minStock} in stock` : 'stop reordering');
  const urgency = b.days_left <= 0 ? 3 : b.days_left <= 30 ? 2 : 1;
  const value = +(b.expiry_units * b.unit_cost).toFixed(2);

  out.push({ json: {
    action_id: `${b.batch_id}-${run_date}`, run_date, batch_id: b.batch_id,
    branch_id: b.branch_id, branch_name: branch[b.branch_id]?.name || b.branch_id,
    sku: b.sku, drug_name: b.drug_name, batch_no: b.batch_no, schedule: b.schedule, criticality: b.criticality,
    days_left: b.days_left, expiry_units: b.expiry_units, value_at_risk: value,
    flags: f.join(', '),
    transfer_units: plan.transfer, transfer_to: plan.transfer ? best.name : '',
    transfer_to_email: plan.transfer ? best.email : '', transfer_cold: b.storage === 'cold',
    return_units: plan.ret, supplier_id: b.supplier_id, supplier_name: s?.supplier_name || '',
    supplier_email: s?.supplier_email || '',
    return_credit: plan.ret ? +(plan.ret * b.unit_cost * (+s.credit_pct / 100)).toFixed(2) : 0,
    discount_units: plan.disc, dispose_units: plan.disp,
    reorder_status: never ? 'MIN_STOCK' : 'STOP', min_stock_units: never ? minStock : 0,
    reorder_policy: never ? `KEEP_MIN_SAFETY_STOCK (${minStock} units)` : 'STOP_REORDER_UNTIL_CLEARED',
    plan_text: (controlled ? 'MANUAL (controlled drug): ' : '') + parts.join(', '),
    summary: b.days_left <= 0 ? `${b.expiry_units} units of ${b.drug_name} (batch ${b.batch_no}) EXPIRED ${-b.days_left} days ago` : `${b.expiry_units} units of ${b.drug_name} (batch ${b.batch_no}) will probably expire in ${b.days_left} days`,
    priority_score: value * urgency + (never ? 1000 : 0)
  } });
}
return out.sort((a, b) => b.json.priority_score - a.json.priority_score).slice(0, cfg.top_n);

